def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    colors = [v for v in counts if v != background]
    rail = max(colors, key=lambda v: counts[v])
    marker = max(v for v in colors if v != rail)

    # Vertical parallel rails: draw a ray from each point toward its rail,
    # and copy the ray as a full stroke on the offset rail segment.
    rail_cols = [c for c in range(w)
                 if sum(grid[r][c] == rail for r in range(h)) >= 2]
    if len(rail_cols) >= 2:
        left, right = min(rail_cols), max(rail_cols)
        left_rows = [r for r in range(h) if grid[r][left] == rail]
        right_rows = [r for r in range(h) if grid[r][right] == rail]
        offset = right_rows[0] - left_rows[0]
        for r in range(h):
            for c in range(w):
                if grid[r][c] != marker:
                    continue
                g[r][c] = 4
                if left_rows[0] <= r <= left_rows[-1]:
                    for x in range(left + 1, c):
                        g[r][x] = marker
                    target = r + offset
                elif right_rows[0] <= r <= right_rows[-1]:
                    for x in range(c + 1, right):
                        g[r][x] = marker
                    target = r - offset
                else:
                    continue
                if 0 <= target < h:
                    for x in range(left + 1, right):
                        g[target][x] = marker
        return g

    # Horizontal parallel rails use the same rule with rows and columns exchanged.
    rail_rows = [r for r in range(h)
                 if sum(grid[r][c] == rail for c in range(w)) >= 2]
    if len(rail_rows) >= 2:
        top, bottom = min(rail_rows), max(rail_rows)
        top_cols = [c for c in range(w) if grid[top][c] == rail]
        bottom_cols = [c for c in range(w) if grid[bottom][c] == rail]
        offset = bottom_cols[0] - top_cols[0]
        for r in range(h):
            for c in range(w):
                if grid[r][c] != marker:
                    continue
                g[r][c] = 4
                if top_cols[0] <= c <= top_cols[-1]:
                    for y in range(top + 1, r):
                        g[y][c] = marker
                    target = c + offset
                elif bottom_cols[0] <= c <= bottom_cols[-1]:
                    for y in range(r + 1, bottom):
                        g[y][c] = marker
                    target = c - offset
                else:
                    continue
                if 0 <= target < w:
                    for y in range(top + 1, bottom):
                        g[y][target] = marker
    return g

